    env,
    io::{self, IsTerminal, Write},
    path::Path,
    process::ExitCode,
};
use term::{clear_terminal, press_enter_prompt};

use crate::{
    app_state::AppState,
    cli::{Args, Command},
    editor::Editor,
    info_file::InfoFile,
};

mod app_state;
mod cargo_toml;
